-- RealTimeDrawingApplication PostgreSQL schema
-- Run this script once against the database named in OnlineDatabase.
-- The application also runs EnsureCreated() at startup, so this script is
-- optional for a new database and useful for controlled server provisioning.

CREATE TABLE IF NOT EXISTS "SchemaMigrations" (
    "Version" text PRIMARY KEY,
    "AppliedAtUtc" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "Accounts" (
    "AccountId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Email" text NOT NULL,
    "FullName" text NOT NULL,
    "PasswordHash" text NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_Accounts_Email"
    ON "Accounts" ("Email");

CREATE TABLE IF NOT EXISTS "Projects" (
    "ProjectId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ProjectName" text NOT NULL,
    "UserAccountId" integer NULL,
    CONSTRAINT "FK_Projects_Accounts_UserAccountId"
        FOREIGN KEY ("UserAccountId") REFERENCES "Accounts" ("AccountId")
        ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS "IX_Projects_UserAccountId"
    ON "Projects" ("UserAccountId");

CREATE TABLE IF NOT EXISTS "ShareUserProjects" (
    "ShareUserId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Email" text NOT NULL,
    "UsersAccountId" integer NULL,
    "ProjectProjectId" integer NULL,
    CONSTRAINT "FK_ShareUserProjects_Accounts_UsersAccountId"
        FOREIGN KEY ("UsersAccountId") REFERENCES "Accounts" ("AccountId")
        ON DELETE RESTRICT,
    CONSTRAINT "FK_ShareUserProjects_Projects_ProjectProjectId"
        FOREIGN KEY ("ProjectProjectId") REFERENCES "Projects" ("ProjectId")
        ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS "IX_ShareUserProjects_UsersAccountId"
    ON "ShareUserProjects" ("UsersAccountId");

CREATE INDEX IF NOT EXISTS "IX_ShareUserProjects_ProjectProjectId"
    ON "ShareUserProjects" ("ProjectProjectId");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_ShareUserProjects_Email_ProjectProjectId"
    ON "ShareUserProjects" ("Email", "ProjectProjectId");

CREATE TABLE IF NOT EXISTS "DrawingComponentModels" (
    "DrawingComponentId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Title" text NOT NULL,
    "X" double precision NOT NULL,
    "Y" double precision NOT NULL,
    "Width" double precision NOT NULL,
    "Height" double precision NOT NULL,
    "LineThickness" integer NOT NULL,
    "StrokeThickness" integer NOT NULL,
    "SelectedStroke" text NOT NULL,
    "SelectedFillColor" text NOT NULL,
    "SelectedBorderColor" text NOT NULL,
    "ProjectProjectId" integer NULL,
    CONSTRAINT "FK_DrawingComponentModels_Projects_ProjectProjectId"
        FOREIGN KEY ("ProjectProjectId") REFERENCES "Projects" ("ProjectId")
        ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS "IX_DrawingComponentModels_ProjectProjectId"
    ON "DrawingComponentModels" ("ProjectProjectId");
